window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[313]={"id":"313","numero":313,"titre":"Tumeurs du testicule","objectifs":[{"id":"313-1","rang":"A","rubrique":"Définition","titre":"Connaître les trois principaux types histologiques des tumeurs du testicule dont les tumeurs germinales du testicule","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs malignes du testicule sont à <span class=\"kw-chiffre\">95 %</span> des <span class=\"kw-def\">tumeurs germinales</span>, issues de la transformation des cellules primitives de la spermatogenèse au <span class=\"kw-def\">contact</span> de la membrane basale des <span class=\"kw-def\">tubes séminifères</span>. Les <span class=\"kw-chiffre\">5 %</span> restants proviennent du <span class=\"kw-def\">stroma testiculaire</span> (Sertoli, Leydig). On distingue donc <strong>trois grands types histologiques</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Origine / particularités</th><th>Marqueurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">TGNS</span> — Tumeurs Germinales Non Séminomateuses</td>\n            <td><span class=\"kw-chiffre\">55 %</span></td>\n            <td>Tumeurs <strong>mosaïques</strong>, plusieurs contingents embryonnaires : <span class=\"kw-def\">tératome</span>, <span class=\"kw-def\">carcinome embryonnaire</span>, <span class=\"kw-def\">tumeur du sac vitellin</span>, <span class=\"kw-def\">choriocarcinome</span>. Croissance plus rapide, chimiosensibles.</td>\n            <td><span class=\"kw-bio\">AFP</span> (<span class=\"kw-clinique\">carcinome</span> embryonnaire, sac vitellin) · <span class=\"kw-bio\">hCG</span> (choriocarcinome)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">TGS</span> — Tumeurs Germinales Séminomateuses</td>\n            <td><span class=\"kw-chiffre\">45 %</span></td>\n            <td><span class=\"kw-def\">Séminome pur</span>, tumeur <strong>homogène</strong>, sans <span class=\"kw-bio\">différenciation</span> embryonnaire. Meilleur <span class=\"kw-def\">pronostic</span>, très radiosensible.</td>\n            <td><span class=\"kw-bio\">hCG</span> dans <span class=\"kw-chiffre\">~20 %</span> des cas (cellules syncytiotrophoblastiques) · <span class=\"kw-bio\">AFP</span> <span class=\"kw-alerte\">jamais augmentée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tumeurs non germinales</span></td>\n            <td><span class=\"kw-chiffre\">5 %</span></td>\n            <td><strong>Stromales :</strong> tumeurs à cellules de <span class=\"kw-def\">Sertoli</span> / <span class=\"kw-def\">Leydig</span> (bénignes dans <span class=\"kw-chiffre\">90 %</span> des cas). <br><strong>Mixtes :</strong> gonadoblastome. <br><strong>Autres :</strong> adénocarcinome du rete testis, mésothéliome de la vaginale, localisations secondaires (prostate, rein, <span class=\"kw-clinique\">mélanome</span>, <span class=\"kw-def\">lymphome</span> chez le sujet âgé).</td>\n            <td>Pas de marqueur spécifique</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Détail des sous-types TGNS</strong> (souvent mélangés au sein d'une même tumeur) :</p>\n      <ul>\n        <li><span class=\"kw-def\">Tératome</span> — dérive des 3 feuillets embryonnaires.</li>\n        <li><span class=\"kw-def\">Carcinome embryonnaire</span> — très agressif, sécrète <span class=\"kw-bio\">AFP</span>.</li>\n        <li><span class=\"kw-def\">Tumeur du sac vitellin</span> (vitelline) — typique chez l'enfant, sécrète <span class=\"kw-bio\">AFP</span>.</li>\n        <li><span class=\"kw-def\">Choriocarcinome</span> — très vascularisé, métastatique, sécrète <span class=\"kw-bio\">hCG</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Règle d'or histopathologique :</strong> dans une tumeur mosaïque, <span class=\"kw-alerte\">le moindre contingent non séminomateux fait classer l'ensemble comme TGNS</span> — même s'il existe par ailleurs un large contingent séminomateux. C'est ce qui conditionne le traitement adjuvant (<span class=\"kw-ttt\">chimiothérapie</span> <span class=\"kw-bio\">vs</span> radiothérapie).</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> TGNS sont des <span class=\"kw-def\">puzzles de tissus embryonnaires</span> ; le TGS est <strong>seul</strong>, c'est le <span class=\"kw-def\">séminome pur</span>. <span class=\"kw-bio\">AFP</span> → embryon &amp; vitellus ; <span class=\"kw-bio\">hCG</span> → choriocarcinome (hormone de <span class=\"kw-ci\">grossesse</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeurs de la prostate · 311 — Tumeurs du rein de l’adulte · 312 — Tumeurs du sein</em></p>","frequence":0},{"id":"313-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les données épidémiologiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tumeurs germinales du testicule</span> sont rares mais d'importance pédagogique majeure : elles touchent l'<strong>homme jeune</strong> et figurent parmi les cancers les <strong>plus curables</strong> du corpus.</p>\n      <table >\n        <thead><tr><th>Donnée</th><th>Repère chiffré</th></tr></thead>\n        <tbody>\n          <tr><td>Part dans <span class=\"kw-clinique\">les</span> tumeurs solides de l'homme</td><td><span class=\"kw-chiffre\">1,5 %</span></td></tr>\n          <tr><td>Rang parmi <span class=\"kw-clinique\">les</span> tumeurs urologiques</td><td><span class=\"kw-chiffre\">4ᵉ</span> rang (après prostate, vessie / voies excrétrices, rein)</td></tr>\n          <tr><td><span class=\"kw-def\">Incidence</span> (France)</td><td><span class=\"kw-chiffre\">8,7</span> nouveaux cas / <span class=\"kw-chiffre\">100 000</span> hommes / an, soit <span class=\"kw-chiffre\">~2 700</span> cas / an — <span class=\"kw-alerte\">en forte augmentation</span></td></tr>\n          <tr><td>Pic d'<span class=\"kw-def\">incidence</span> par sous-type</td><td><strong>TGNS :</strong> <span class=\"kw-chiffre\">30-34 ans</span> · <strong>TGS :</strong> <span class=\"kw-chiffre\">~40 ans</span></td></tr>\n          <tr><td>Place dans le cancer du sujet jeune</td><td><span class=\"kw-alerte\">Cancer le plus fréquent chez l'homme &lt; 35 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span></td><td>En diminution — caractérisé par sa <span class=\"kw-def\">rareté</span> et sa <span class=\"kw-def\">particulière curabilité</span></td></tr>\n          <tr><td>Survie à<span class=\"kw-chiffre\"> 5 ans</span> (tous stades confondus)</td><td><span class=\"kw-chiffre\">&gt; 95 %</span> — très bon <span class=\"kw-def\">pronostic</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute <span class=\"kw-clinique\">tuméfaction</span> scrotale chez un homme jeune (<span class=\"kw-chiffre\">20-40 ans</span>) doit faire évoquer une tumeur germinale <em>jusqu'à preuve du contraire</em> — l'<span class=\"kw-def\">épidémiologie</span> commande le réflexe diagnostique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 292 — Diagnostic des cancers</em></p>","frequence":0},{"id":"313-3","rang":"B","rubrique":"Etiologie","titre":"Connaître l’histoire naturelle des tumeurs germinales du testicule","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs germinales se développent à partir d'un précurseur intra-tubulaire, la <span class=\"kw-def\">néoplasie germinale in situ</span> (<span class=\"kw-def\">NGIS</span>), <strong>état précancéreux</strong> qui concerne la majorité des tumeurs germinales du testicule.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">NGIS</span> (précurseur)</td>\n            <td><span class=\"kw-clinique\">Lésion</span> intra-tubulaire, état pré-cancéreux, point de départ commun aux TGS et TGNS.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Stade localisé</span></td>\n            <td><span class=\"kw-chiffre\">60-70 %</span> des cas au diagnostic. Croissance volumique locale dans la pulpe testiculaire, <span class=\"kw-alerte\">plus rapide pour les TGNS</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Extension lymphophile</span></td>\n            <td>\n              <strong>Principalement :</strong> ganglions rétropéritonéaux axiaux <span class=\"kw-clinique\">péricaves</span> et <span class=\"kw-clinique\">périaortiques</span>. <br>\n              <strong>Moins fréquemment :</strong> ganglions pelviens iliaques, <span class=\"kw-clinique\">médiastinaux antérieurs et moyens</span>, sus-claviculaire gauche (Troisier).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Extension hématogène</span></td>\n            <td>\n              <strong>Principal site :</strong> <span class=\"kw-imagerie\">poumons</span>. <br>\n              <strong>Plus rares :</strong> foie, cerveau, os.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège anatomique.</strong> Le <span class=\"kw-ttt\">drainage</span> lymphatique du testicule suit le <strong>cordon spermatique</strong> vers <span class=\"kw-clinique\">les</span> ganglions <span class=\"kw-alerte\">rétropéritonéaux</span>, <em>pas</em> vers les ganglions inguinaux. Une <span class=\"kw-bio\">biopsie</span> scrotale détournerait ce drainage vers les ganglions inguinaux — c'est l'argument anatomique majeur de la <span class=\"kw-alerte\">contre-indication absolue de la biopsie trans-scrotale</span>.</div>","frequence":1},{"id":"313-4","rang":"B","rubrique":"Etiologie","titre":"Connaître les facteurs de risque des tumeurs germinales du testicule","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> (FdR) des tumeurs germinales sont à connaître <strong>ainsi que les non-FdR pièges</strong> souvent demandés en QCM.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Antécédents personnels</td>\n            <td>ATCD de <span class=\"kw-etio\">tumeur germinale controlatérale</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Antécédents familiaux</span></td>\n            <td>ATCD familial de tumeur germinale au <span class=\"kw-etio\">1<sup>er</sup> degré</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Syndrome de dysgénésie</span> testiculaire</td>\n            <td>\n              <span class=\"kw-etio\">Cryptorchidie</span> <strong>(FdR majeur)</strong> ; <br>\n              <span class=\"kw-etio\">Ectopie testiculaire</span> ; <br>\n              <span class=\"kw-etio\">Atrophie testiculaire</span> (<span class=\"kw-chiffre\">&lt; 12 mL</span>) ; <br>\n              <span class=\"kw-etio\">Infertilité</span> ; <br>\n              <span class=\"kw-etio\">Hypospadias</span>.\n            </td>\n          </tr>\n          <tr>\n            <td>Maladies syndromiques</td>\n            <td>\n              <span class=\"kw-etio\">Trisomie 21</span> (Down) ; <br>\n              <span class=\"kw-etio\">Syndrome de Klinefelter</span> (tumeurs germinales <em>extragonadiques</em> médiastinales).\n            </td>\n          </tr>\n          <tr>\n            <td>FdR comportemental</td>\n            <td><span class=\"kw-ttt\">Cannabis</span> — consommation régulière et prolongée, surtout pour <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">TGNS</span>.</td>\n          </tr>\n          <tr>\n            <td>FdR environnementaux</td>\n            <td>Exposition aux <span class=\"kw-etio\">pesticides</span>, <span class=\"kw-etio\">perturbateurs endocriniens</span> (en cours d'étude).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pièges classiques EDN — NE SONT PAS des FdR :</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Microlithiases testiculaires isolées</span> — ne doivent pas être considérées comme un FdR (à distinguer de l'atrophie ou de la dysgénésie).</li>\n          <li><span class=\"kw-alerte\">Tabac</span> — n'est pas un FdR de tumeur germinale du testicule (contrairement à la plupart des autres cancers urologiques).</li>\n        </ul>\n      </div>","frequence":1},{"id":"313-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques des tumeurs du testicule","contenu":"<p><span class=\"kw-clinique\">Les</span> circonstances de découverte sont stéréotypées et opposent <strong>présentation locale fréquente</strong> (l'homme jeune palpe une <span class=\"kw-clinique\">masse</span>) à <strong>présentations indirectes rares</strong> (révélation métastatique ou <span class=\"kw-etio\">paranéoplasique</span>).</p>\n      <table >\n        <thead><tr><th>Type de circonstance</th><th>Présentations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Fréquentes</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Simple pesanteur</span></strong> du testicule ; <br>\n              <strong><span class=\"kw-clinique\">Masse scrotale</span></strong> à l'examen clinique ou à l'<strong>auto-palpation</strong> du patient.\n            </td>\n          </tr>\n          <tr>\n            <td>Rares — locales atypiques</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Douleur testiculaire subaiguë</span></strong> : mime un traumatisme, une <span class=\"kw-def\">orchite</span> ou une <span class=\"kw-def\">torsion</span> ; <br>\n              <strong>Fortuit</strong> lors d'une <span class=\"kw-imagerie\">échographie</span> pour bilan d'<span class=\"kw-clinique\">infertilité</span> (<span class=\"kw-def\">incidence</span> supérieure de l'infertilité chez <span class=\"kw-clinique\">les</span> patients atteints).\n            </td>\n          </tr>\n          <tr>\n            <td>Rares — <span class=\"kw-etio\">paranéoplasique</span></td>\n            <td><strong><span class=\"kw-clinique\">Gynécomastie</span></strong> en lien avec une sécrétion <span class=\"kw-etio\">tumorale</span> d'<span class=\"kw-bio\">hCG</span> (évoque fortement une tumeur germinale).</td>\n          </tr>\n          <tr>\n            <td>Rares — métastatiques</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Altération de l'état général</span></strong> (<span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">perte de poids</span>) ; <br>\n              <strong><span class=\"kw-clinique\">Douleur ou masse abdominale</span></strong> liée à de volumineuses <span class=\"kw-clinique\">adénopathies</span> rétropéritonéales ; <br>\n              <strong><span class=\"kw-clinique\">Ganglion de Troisier</span></strong> (sus-claviculaire gauche) ; <br>\n              <strong><span class=\"kw-clinique\">Détresse respiratoire / toux</span></strong> exceptionnellement liée aux métastases pulmonaires.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège EDN — <span class=\"kw-clinique\">Gynécomastie</span>.</strong> <span class=\"kw-alerte\">Toute gynécomastie chez l'homme jeune doit faire palper les testicules</span> et doser <span class=\"kw-bio\">hCG</span> totale : le choriocarcinome (et plus largement <span class=\"kw-clinique\">les</span> TGNS) en sont une cause classique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 246 — <span class=\"kw-clinique\">Gynécomastie</span></em></p>","frequence":1},{"id":"313-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de l’examen clinique du testicule tumoral","contenu":"<p>L'examen clinique d'une suspicion de tumeur testiculaire repose sur une <strong>palpation comparative bilatérale</strong>, debout puis couché. Cinq critères sémiologiques sont à connaître.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Consistance</span></td>\n            <td><span class=\"kw-clinique\">Masse</span> <strong><span class=\"kw-clinique\">dure</span></strong> voire <strong><span class=\"kw-clinique\">pierreuse</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Caractère</span></td>\n            <td><strong><span class=\"kw-clinique\">Unilatérale</span></strong>, <strong><span class=\"kw-clinique\">circonscrite</span></strong>, intra-scrotale.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleur</span></td>\n            <td>Sensible mais classiquement <span class=\"kw-alerte\">indolore</span> (la <span class=\"kw-clinique\">masse</span> non douloureuse n'élimine pas le diagnostic — au contraire).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Transillumination</span></td>\n            <td><span class=\"kw-alerte\">Non transilluminable</span> (à la différence d'une <span class=\"kw-def\">hydrocèle</span>, qui transillumine).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Signe de Chevassu</span></td>\n            <td><strong>Positif</strong> = <span class=\"kw-def\">sillon épididymo-testiculaire conservé</span>, signant l'origine <span class=\"kw-alerte\">testiculaire pure</span> de la <span class=\"kw-clinique\">masse</span>, indépendante de l'épididyme.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-def\">Chevassu positif</span> = on peut <em>séparer</em> au doigt le testicule de l'épididyme — donc la <span class=\"kw-clinique\">masse</span> est <strong>intra-testiculaire</strong>. <span class=\"kw-def\">Chevassu négatif</span> = masse englobant l'épididyme, oriente plutôt vers une <span class=\"kw-def\">orchi-épididymite</span>.</div>","frequence":1},{"id":"313-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique","contenu":"<p>La démarche diagnostique d'une tumeur du testicule suit l'<strong>algorithme du Collège de cancérologie en 5 étapes</strong>, articulant clinique → imagerie → bilan <span class=\"kw-ttt\">biologique</span> → <span class=\"kw-ttt\">chirurgie</span> → <span class=\"kw-def\">stadification</span>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Geste</th><th>Justification</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Circonstances de découverte</strong></td>\n            <td><span class=\"kw-clinique\">Examen clinique</span> bilatéral comparatif (palpation testiculaire, recherche de <span class=\"kw-clinique\">gynécomastie</span>, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-clinique\">masse</span> abdominale, Troisier).</td>\n            <td>Réflexe : <span class=\"kw-clinique\">tuméfaction</span> scrotale chez homme jeune = tumeur germinale JPDC.</td>\n          </tr>\n          <tr>\n            <td><strong>2. Imagerie de 1<sup>re</sup> intention</strong></td>\n            <td><span class=\"kw-imagerie\">Échographie scrotale</span> bilatérale avec <strong><span class=\"kw-imagerie\">Doppler</span> couleur</strong>.</td>\n            <td>Confirme la localisation testiculaire, élimine origine extra-testiculaire, oriente vers la nature maligne.</td>\n          </tr>\n          <tr>\n            <td><strong>3. Bilan présomptif</strong> (avant orchidectomie)</td>\n            <td>\n              <span class=\"kw-ttt\">Cryoconservation</span> de sperme au <span class=\"kw-def\">CECOS</span> ; <br>\n              Dosage des <strong>3 marqueurs sériques</strong> : <span class=\"kw-bio\">AFP</span>, <span class=\"kw-bio\">hCG totale</span>, <span class=\"kw-bio\">LDH</span> ; <br>\n              <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> (<span class=\"kw-imagerie\">TDM</span>-TAP).\n            </td>\n            <td>Préservation fertilité (obl<span class=\"kw-chiffre\">iga</span>tion médico-légale), valeur diagnostique &amp; pronostique des marqueurs, <span class=\"kw-def\">bilan d'extension</span> complet.</td>\n          </tr>\n          <tr>\n            <td><strong>4. Orchidectomie totale</strong></td>\n            <td><span class=\"kw-ttt\">Orchidectomie totale élargie au cordon spermatique</span>, par <strong>voie inguinale</strong> impérative. <br><em>L<span class=\"kw-chiffre\">iga</span>ture 1<sup>re</sup> du cordon à l'orifice inguinal interne</em>, <span class=\"kw-ttt\">exérèse</span> en bloc, prothèse testiculaire optionnelle dans le même temps.</td>\n            <td>Dernier geste diagnostique + 1<sup>er</sup> geste thérapeutique. Permet l'<span class=\"kw-bio\">histologie</span> définitive.</td>\n          </tr>\n          <tr>\n            <td><strong>5. <span class=\"kw-def\">Stadification</span></strong></td>\n            <td>Comparaison marqueurs post-op + <span class=\"kw-imagerie\">TDM</span>-TAP : <br><strong>Localisé</strong> = marqueurs normalisés <em>et</em> <span class=\"kw-imagerie\">TDM</span> normale. <br><strong>Métastatique</strong> = marqueurs non normalisés <em>et/ou</em> <span class=\"kw-imagerie\">TDM</span> anormale.</td>\n            <td>L'absence de normalisation des marqueurs après orchidectomie suffit à classer M+ même si <span class=\"kw-imagerie\">TDM</span> normale.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span> — Geste PROSCRIT.</strong> La <span class=\"kw-ci\">biopsie percutanée (trans-scrotale)</span> d'une tumeur germinale du testicule est <span class=\"kw-alerte\">absolument contre-indiquée</span> : elle violerait l'anatomie lymphatique (<span class=\"kw-ttt\">drainage</span> scrotal vers ganglions inguinaux au lieu du drainage testiculaire vers ganglions rétropéritonéaux) et risquerait de disséminer la tumeur. Le diagnostic histologique se fait <strong>uniquement sur la pièce d'<span class=\"kw-ttt\">orchidectomie</span></strong>.</div>\n      <div class=\"callout callout-warn\"><strong>Cas particulier (rang C).</strong> Une <span class=\"kw-ttt\">orchidectomie partielle</span> par voie inguinale (conservation d'organe) peut être discutée si <strong>testicule unique</strong> ou <strong>tumeurs bilatérales synchrones</strong> (exceptionnelles), ou pour confirmer une <span class=\"kw-clinique\">lésion</span> bénigne suspectée à l'<span class=\"kw-imagerie\">échographie</span> (kyste épidermoïde, tumeur de Leydig).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 294 — Traitement des cancers</em></p>","frequence":2},{"id":"313-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’examen de première intention : échographie scrotale","contenu":"<p>L'<span class=\"kw-imagerie\">échographie scrotale</span> est l'examen <strong>paraclinique de 1<sup>re</sup> intention</strong> devant tout <span class=\"kw-clinique\">nodule</span> intra-testiculaire. Bilatérale avec <span class=\"kw-imagerie\">Doppler</span> couleur, elle remplit <strong>trois missions</strong> : confirmer la localisation testiculaire, explorer le controlatéral, orienter vers la nature maligne.</p>\n      <ul>\n        <li><strong>Confirme la localisation testiculaire</strong> — élimine une origine extra-testiculaire (ex. <span class=\"kw-def\">kyste de l'épididyme</span>).</li>\n        <li><strong>Explore le testicule controlatéral</strong> — recherche d'une tumeur synchrone, de <span class=\"kw-imagerie\">microcalcifications</span>, d'une atrophie.</li>\n        <li><strong>Oriente vers la nature maligne</strong> — toute tumeur germinale est <span class=\"kw-imagerie\">vascularisée au Doppler couleur</span>.</li>\n      </ul>\n      <p><strong>Aspect échographique selon le sous-type histologique :</strong></p>\n      <table >\n        <thead><tr><th>Sous-type</th><th>Aspect échographique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">TGS</span> — Séminome</td>\n            <td>Masses <strong>lobulées</strong>, <span class=\"kw-imagerie\">hypoéchogènes</span>, assez <strong>homogènes</strong>, fréquemment associées à des <span class=\"kw-imagerie\">microlithes</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">TGNS</span></td>\n            <td>Masses volontiers <strong>hétérogènes</strong>, <span class=\"kw-imagerie\">polycycliques</span> (plages kystiques + zones tissulaires mixtes).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Kyste épidermoïde</span> (bénin)</td>\n            <td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-imagerie\">hypoéchogène</span>, <strong>ovalaire</strong>, <strong>bien limitée</strong>, <strong>peu vascularisée</strong> au <span class=\"kw-imagerie\">Doppler</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tumeur de Leydig</span> (bénigne dans <span class=\"kw-chiffre\">90 %</span>)</td>\n            <td><span class=\"kw-clinique\">Nodule</span> bien limité, souvent hypoéchogène, hypervascularisé — peut justifier une orchidectomie <em>partielle</em>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-imagerie\">échographie scrotale</span> ne fait <em>jamais</em> le diagnostic histologique — elle oriente. Le diagnostic de certitude reste l'<span class=\"kw-ttt\">orchidectomie</span> avec analyse anatomopathologique.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/unilateral-testicular-lesions","label":"Radiopaedia : Unilateral testicular lesions"},{"href":"https://radiopaedia.org/articles/bilateral-testicular-lesions","label":"Radiopaedia : Bilateral testicular lesions"},{"href":"https://radiopaedia.org/articles/testicular-cancer","label":"Radiopaedia : Testicular cancer"}]},{"id":"313-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan d’extension : tomodensitométrie thoraco-abdomino-pelvienne et les trois marqueurs sériques : alpha-foeto-protéine (AFP), hormone chorionique gonadotrophique (HCG) totales et lactico-deshydrogénases (LDH)","contenu":"<p>Le <span class=\"kw-def\">bilan d'extension</span> d'une tumeur germinale repose sur <strong>deux piliers</strong> indissociables : la <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> et le dosage <strong>systématique</strong> des <strong>3 marqueurs sériques</strong> (<span class=\"kw-bio\">AFP</span>, <span class=\"kw-bio\">hCG totale</span>, <span class=\"kw-bio\">LDH</span>), <strong>avant ET après orchidectomie</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pilier 1 — Imagerie : <span class=\"kw-imagerie\">TDM</span> thoraco-abdomino-pelvienne</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">TDM-TAP</span> avec injection : <strong>pierre angulaire</strong> du <span class=\"kw-def\">bilan d'extension</span>.</li>\n        <li>Recherche systématique des <span class=\"kw-clinique\">adénopathies rétropéritonéales</span> (péricaves, périaortiques) et des <span class=\"kw-clinique\">métastases viscérales</span> (poumons +++, foie, cerveau, os).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pilier 2 — Marqueurs sériques (<span class=\"kw-bio\">AFP</span>, hCG totale, <span class=\"kw-bio\">LDH</span>)</h4>\n      <p>Triple intérêt : <strong>diagnostique</strong> (avant orchidectomie), <strong>pronostique</strong> (après orchidectomie, entre dans la <span class=\"kw-def\">classification</span> <span class=\"kw-def\">IGCCCG</span>), <strong><span class=\"kw-def\">suivi</span></strong> (cinétique, demi-vies).</p>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Demi-vie</th><th>Commentaires généraux</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">AFP</span> (alpha-fœto-protéine)</td>\n            <td><span class=\"kw-chiffre\">5-7 jours</span></td>\n            <td><strong>Non spécifique :</strong> aussi en oncologie digestive (<span class=\"kw-def\">CHC</span>, pancréas, estomac) et certaines hépatopathies non tumorales.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">hCG totale</span></td>\n            <td><span class=\"kw-chiffre\">24-36 h</span></td>\n            <td>On dose l'<strong>hCG totale</strong>, jamais la seule β-hCG.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">LDH</span> (lactico-déshydrogénases)</td>\n            <td>Variable</td>\n            <td><strong>Non spécifique</strong> — corrélée au <em>turn-over</em> cellulaire, reflet de la <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Profil des marqueurs selon le sous-type histologique</strong> (transcription du tableau Urofrance) :</p>\n      <table >\n        <thead><tr><th>Sous-type</th><th><span class=\"kw-bio\">AFP</span></th><th>hCG totale</th><th><span class=\"kw-bio\">LDH</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Séminome pur</span></td>\n            <td>Jamais augmentée ✗</td>\n            <td>Augmentée dans <span class=\"kw-chiffre\">~20 %</span> des cas</td>\n            <td>Possible</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Carcinome embryonnaire</span></td>\n            <td>Augmentée ✓</td>\n            <td>—</td>\n            <td>Possible</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Choriocarcinome</span></td>\n            <td>—</td>\n            <td>Augmentation très importante ✓</td>\n            <td>Possible</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tumeur du sac vitellin</span></td>\n            <td>Augmentée ✓</td>\n            <td>—</td>\n            <td>Possible</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges classiques EDN sur <span class=\"kw-clinique\">les</span> marqueurs.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">L'AFP n'est JAMAIS augmentée dans le séminome pur.</span> Si <span class=\"kw-bio\">AFP</span> ↑ chez un patient avec un aspect de séminome → il existe forcément un <strong>contingent non séminomateux</strong> → classer en <span class=\"kw-def\">TGNS</span>.</li>\n          <li>Augmentation importante de l'hCG totale → en faveur d'un <span class=\"kw-def\">choriocarcinome</span> (ou TGNS avec contingent choriocarcinomateux).</li>\n          <li><span class=\"kw-alerte\">Absence de normalisation des marqueurs après orchidectomie</span> = patient classé en <span class=\"kw-def\">stade métastatique</span>, même si la <span class=\"kw-imagerie\">TDM</span>-TAP est normale.</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pilier 3 — <span class=\"kw-def\">Stadification</span> après orchidectomie</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Stade localisé</span></td>\n            <td>Marqueurs tumoraux <strong>normaux ou normalisés</strong> <em>ET</em> <span class=\"kw-imagerie\">TDM-TAP normale</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Stade métastatique</span></td>\n            <td>Marqueurs <strong>non normalisés</strong> <em>ET/OU</em> <span class=\"kw-imagerie\">TDM-TAP anormale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> pronostique IGCCCG (rang C, à connaître de nom)</h4>\n      <p>La <span class=\"kw-def\">classification IGCCCG</span> (<em>International Germ Cell Cancer Collaborative Group</em>, 1997) stratifie <span class=\"kw-clinique\">les</span> tumeurs germinales <strong>métastatiques</strong> en groupes pronostiques selon : le <strong>sous-type histologique</strong> (TGS <span class=\"kw-bio\">vs</span> TGNS), la <strong>localisation primitive</strong> (testiculaire/rétropéritonéale <span class=\"kw-bio\">vs</span> médiastinale pour les TGNS), la présence de <span class=\"kw-clinique\">métastases viscérales non pulmonaires</span> (foie, cerveau, os) et les <strong>valeurs des marqueurs post-orchidectomie</strong> (<span class=\"kw-bio\">AFP</span>, <span class=\"kw-bio\">hCG</span>, <span class=\"kw-bio\">LDH</span>).</p>\n      <table >\n        <thead><tr><th>Sous-type</th><th>Groupes pronostiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">TGS</span> (séminome pur)</td>\n            <td><strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>roupes uniquement</strong> : <span class=\"kw-clinique\">bon</span> ou <span class=\"kw-clinique\">intermédiaire</span> — <span class=\"kw-ci\">jamais de</span> « mauvais <span class=\"kw-def\">pronostic</span> » pour un séminome pur.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">TGNS</span></td>\n            <td><strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>roupes</strong> : <span class=\"kw-clinique\">bon</span>, <span class=\"kw-clinique\">intermédiaire</span>, mauvais. Localisation médiastinale primitive = mauvais <span class=\"kw-def\">pronostic</span> d'emblée.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'IGCCCG conditionne le nombre de cycles de <span class=\"kw-ttt\">chimiothérapie</span> (<span class=\"kw-ttt\">BEP × 3</span> bon <span class=\"kw-def\">pronostic</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-ttt\">BEP × 4</span> intermédiaire/mauvais) — détail rang C oncologie. Pour l'EDN, retenir le <strong>principe</strong> et <span class=\"kw-clinique\">les</span> <strong>4 paramètres stratifiants</strong>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examens NON recommandés en routine</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">IRM scrotale</span> ✗ — n'apporte pas d'élément déterminant au bilan local.</li>\n        <li><span class=\"kw-imagerie\">TEP-TDM au 18-FDG</span> ✗ — pas recommandée en <span class=\"kw-def\">bilan d'extension</span> initial.</li>\n        <li><span class=\"kw-imagerie\">IRM encéphalique</span> et/ou <span class=\"kw-imagerie\">IRM hépatique</span> — uniquement sur signes d'appel cliniques.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Préservation de la fertilité — CECOS</h4>\n      <div class=\"callout callout-danger\"><strong>Obl<span class=\"kw-chiffre\">iga</span>tion médico-légale.</strong> <span class=\"kw-alerte\">Cryoconservation de gamètes au <span class=\"kw-def\">CECOS</span></span> (centre d'étude et de conservation des œufs et du sperme humains) doit être <strong>systématiquement proposée avant tout traitement</strong>. Objectif double : (1) évaluer la capacité procréative initiale du patient ; (2) préserver la possibilité d'une paternité ultérieure (<span class=\"kw-ttt\">chimiothérapie</span> / radiothérapie sont gonadotoxiques). <br>\n      <strong>Supplémentation hormonale post-orchidectomie unilatérale : non nécessaire ✗</strong> — le testicule controlatéral assure une synthèse suffisante de testostérone.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d’un malade cancéreux</em></p>","frequence":2},{"id":"313-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels : tumeurs testiculaires bénignes, tumeurs extra-testiculaires","contenu":"<p><span class=\"kw-alerte\">Toute tuméfaction scrotale chez un homme jeune doit faire évoquer de principe une tumeur germinale</span> 🚩 — mais plusieurs diagnostics différentiels sont à connaître pour éviter <span class=\"kw-clinique\">les</span> pièges.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Clinique</th><th>Imagerie</th><th>Discriminant</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Orchi-épididymite</span> (principal DD, en particulier <strong><span class=\"kw-clinique\">abcès</span> testiculaire</strong>)</td>\n            <td>\n              <strong>Signes <span class=\"kw-etio\">infectieux</span> :</strong> <span class=\"kw-clinique\">fièvre</span>, douleur scrotale aiguë ; <br>\n              <strong>Troubles urinaires :</strong> brûlures mictionnelles, <span class=\"kw-clinique\">pollakiurie</span> ; <br>\n              <strong>Examen :</strong> <span class=\"kw-def\">Chevassu négatif</span> (<span class=\"kw-clinique\">masse</span> englobant l'épididyme).\n            </td>\n            <td><span class=\"kw-imagerie\">Hypervascularisation</span> de l'épididyme au <span class=\"kw-imagerie\">Doppler</span>.</td>\n            <td><span class=\"kw-bio\">ECBU positif</span> + signes <span class=\"kw-etio\">infectieux</span> + absence de Chevassu.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hydrocèle vaginale</span></td>\n            <td>Augmentation <strong>progressive</strong> du volume scrotal, <strong>indolore</strong>. <br><span class=\"kw-clinique\">Transillumination positive</span>.</td>\n            <td>Épanchement liquidien péri-testiculaire ; testicule morphologiquement <strong>normal</strong>.</td>\n            <td>Transillumination + testicule normal à l'<span class=\"kw-imagerie\">échographie</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Kyste épidermoïde</span> (tumeur bénigne intra-testiculaire)</td>\n            <td><span class=\"kw-clinique\">Masse</span> indolore, palpation parfois identique à une tumeur germinale.</td>\n            <td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-imagerie\">hypoéchogène</span>, <strong>ovalaire</strong>, <strong>bien limitée</strong>, <strong>peu vascularisée</strong>.</td>\n            <td>Aspect échographique évocateur → confirmation histo par <span class=\"kw-ttt\">orchidectomie partielle</span> par voie inguinale (conservation d'organe).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tumeurs à cellules de Leydig / Sertoli</span> (stromales bénignes dans <span class=\"kw-chiffre\">90 %</span>)</td>\n            <td><span class=\"kw-clinique\">Nodule</span> palpable, parfois symptômes endocriniens (<span class=\"kw-clinique\">gynécomastie</span>, virilisation chez l'enfant).</td>\n            <td><span class=\"kw-clinique\">Nodule</span> bien limité, hypoéchogène, hypervascularisé.</td>\n            <td>Confirmation histo par orchidectomie partielle si tumeur conservable.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe — <span class=\"kw-def\">diagnostic différentiel</span> n°1.</strong> L'<span class=\"kw-def\">orchi-épididymite</span> est le DD à connaître par cœur : devant tout scrotum aigu, distinguer infection <span class=\"kw-bio\">vs</span> tumeur sur le trio <span class=\"kw-clinique\">fièvre + brûlures mictionnelles + ECBU+</span> et le <strong>signe de Chevassu</strong>. <span class=\"kw-alerte\">En cas de doute persistant, l'orchidectomie diagnostique l'emporte sur l'antibiothérapie d'épreuve.</span></div>","frequence":0},{"id":"313-11","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Appréhender l’importance d’une prise en charge andrologique concomitante","contenu":"<p>La prise en charge oncologique d'une tumeur germinale du testicule s'accompagne <strong>systématiquement</strong> d'une <span class=\"kw-def\">prise en charge andrologique</span>, intégrée dès le bilan présomptif initial.</p>\n      <table >\n        <thead><tr><th>Volet andrologique</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cryoconservation de gamètes</span> (CECOS)</td>\n            <td>\n              <strong>Quand :</strong> <span class=\"kw-alerte\">systématiquement avant tout traitement</span> (orchidectomie, <span class=\"kw-ttt\">chimiothérapie</span>, radiothérapie). <br>\n              <strong>Statut :</strong> <span class=\"kw-alerte\">obligation médico-légale</span>. <br>\n              <strong>Objectifs :</strong> évaluer la capacité procréative initiale du patient + préserver la paternité ultérieure (gonadotoxicité des traitements adjuvants).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Supplémentation hormonale post-orchidectomie</span></td>\n            <td>\n              <strong>Après orchidectomie unilatérale :</strong> <span class=\"kw-alerte\">non nécessaire ✗</span> — le testicule controlatéral assure le plus souvent une synthèse suffisante de testostérone. <br>\n              <strong>Cas particuliers</strong> (orchidectomie bilatérale, hypogonadisme post-<span class=\"kw-ttt\">chimiothérapie</span>) : à discuter au cas par cas.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin-top:14px;\"><strong><span class=\"kw-def\">Suivi</span> andrologique long terme</strong> (enrichissement Pilly / Collège — au-delà du strict objectif EDN, mais classique en QCM).</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Hypogonadisme tardif</span></td>\n            <td>\n              <strong><span class=\"kw-def\">Surveillance</span> :</strong> dosage de la <span class=\"kw-bio\">testostéronémie matinale</span> à distance de l'orchidectomie et après <span class=\"kw-ttt\">chimiothérapie</span> (<span class=\"kw-ttt\">BEP</span> notamment, gonadotoxique). <br>\n              <strong>Quand supplémenter :</strong> orchidectomie <strong>bilatérale</strong> OU hypogonadisme symptomatique confirmé biologiquement après orchidectomie unilatérale (<em>rare</em>, le controlatéral compense le plus souvent).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Assistance médicale à la procréation</span> (AMP)</td>\n            <td>\n              En cas d'<span class=\"kw-clinique\">infertilité</span> post-traitement et de désir de paternité : utilisation des gamètes <span class=\"kw-def\">cryoconservés au CECOS</span> en pré-traitement, via <strong>ICSI</strong> le plus souvent. <span class=\"kw-alerte\">D'où l'importance capitale de la cryoconservation systématique avant tout traitement.</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Qualité de vie sexuelle</span></td>\n            <td>\n              <strong>Troubles éjaculatoires :</strong> <span class=\"kw-clinique\">anéjaculation</span> possible après <span class=\"kw-ttt\">curage ganglionnaire rétropéritonéal</span> (<span class=\"kw-clinique\">lésion</span> des fibres sympathiques L1-L4) — d'où l'importance du curage <em>nerve-sparing</em> quand indiqué. <br>\n              <strong>Troubles érectiles :</strong> peu fréquents après simple orchidectomie unilatérale ; à dépister systématiquement à l'interrogatoire.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Image corporelle</span></td>\n            <td>\n              <strong>Prothèse testiculaire</strong> à proposer systématiquement, idéalement <em>dans le même temps opératoire</em> que l'orchidectomie (cf. obj-6). Impact psycho-sexuel non négligeable, surtout chez l'homme jeune en couple.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-def\">CECOS</span> n'est pas optionnel : il doit être proposé <em>avant l'orchidectomie</em>, et sa proposition doit être tracée dans le dossier. C'est un point régulièrement tombé en QCM (obl<span class=\"kw-chiffre\">iga</span>tion médico-légale).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 39 — Assistance médicale à la procréation · 246 — <span class=\"kw-clinique\">Gynécomastie</span> · 295 — Prise en charge d’un malade cancéreux</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-18-item-313-tumeurs-du-testicule/","label":"AFU — Chapitre 18 item 313 tumeurs du testicule"},{"href":"https://fac.umc.edu.dz/snv/faculte/BA/2020/1%20la%20spermatogen%C3%A8se%20cours%20.pdf","label":"1 la spermatogenèse cours"}],"cards":[{"i":"169fd4424de9","n":313,"o":"313-1","u":"Définition","t":"Connaître les trois principaux types histologiques des tumeurs du testicule dont les tumeurs germinales du testicule","q":"Pourquoi est-il important de distinguer les TGNS des TGS sur le plan histopathologique, en particulier en cas de tumeur mosaïque ?","a":"<p>Dans une tumeur mosaïque (comprenant plusieurs contingents), le fait de trouver ne serait-ce qu'un <strong>moindre contingent non séminomateux</strong> (même si une large part est séminomateuse) classifie l'ensemble de la tumeur comme <strong>TGNS</strong>. Cette distinction est cruciale car elle conditionne le <strong>traitement adjuvant</strong>, qui sera une chimiothérapie pour les TGNS et une radiothérapie pour les TGS pures.</p>"},{"i":"834589efd63f","n":313,"o":"313-1","u":"Définition","t":"Connaître les trois principaux types histologiques des tumeurs du testicule dont les tumeurs germinales du testicule","q":"Quels sont les trois principaux types histologiques des tumeurs du testicule, en incluant leur fréquence respective ?","a":"<ul><li>Les <strong>Tumeurs Germinales Non Séminomateuses (TGNS)</strong> représentent environ <strong>55%</strong> des cas.</li><li>Les <strong>Tumeurs Germinales Séminomateuses (TGS)</strong> représentent environ <strong>45%</strong> des cas.</li><li>Les <strong>tumeurs non germinales</strong> (stromales, mixtes ou autres) représentent environ <strong>5%</strong> des cas.</li></ul>"},{"i":"948706f2ddc8","n":313,"o":"313-1","u":"Définition","t":"Connaître les trois principaux types histologiques des tumeurs du testicule dont les tumeurs germinales du testicule","q":"Quelles sont les caractéristiques des Tumeurs Germinales Non Séminomateuses (TGNS), des Tumeurs Germinales Séminomateuses (TGS) et leurs marqueurs biologiques associés ?","a":"<ul><li>Les <strong>TGNS</strong> sont des tumeurs <strong>mosaïques</strong>, composées de plusieurs contingents embryonnaires (tératome, carcinome embryonnaire, tumeur du sac vitellin, choriocarcinome). Elles sont caractérisées par une croissance plus rapide et sont chimiosensibles. Les marqueurs associés sont l'<strong>AFP</strong> (pour le carcinome embryonnaire et la tumeur du sac vitellin) et l'<strong>hCG</strong> (pour le choriocarcinome).</li><li>Les <strong>TGS</strong> sont des <strong>séminomes purs</strong>, tumeurs homogènes sans différenciation embryonnaire. Elles ont un meilleur pronostic et sont très radiosensibles. L'<strong>hCG</strong> peut être augmentée dans environ 20% des cas, mais l'<strong>AFP n'est jamais augmentée</strong>.</li></ul>"},{"i":"be294860ea02","n":313,"o":"313-1","u":"Définition","t":"Connaître les trois principaux types histologiques des tumeurs du testicule dont les tumeurs germinales du testicule","q":"Quelle est la nature histologique des tumeurs du testicule dans 95% des cas, et de quelle origine cellulaire proviennent-elles ?","a":"<p>Dans 95% des cas, les tumeurs malignes du testicule sont des <strong>tumeurs germinales</strong>. Elles sont issues de la transformation des cellules primitives de la spermatogenèse.</p>"},{"i":"243cea6df9b8","n":313,"o":"313-5","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du testicule","q":"Quelle est la présentation clinique la plus fréquente des tumeurs du testicule chez l'homme jeune ?","a":"<p>La présentation la plus fréquente est une <strong>simple pesanteur du testicule</strong> ou la découverte d'une <strong>masse scrotale</strong>, soit à l'examen clinique, soit à l'auto-palpation du patient.</p>"},{"i":"a4f0f721270f","n":313,"o":"313-5","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du testicule","q":"Quels sont les signes cliniques de présentation métastatique des tumeurs du testicule ?","a":"<ul><li>Une <strong>altération de l'état général</strong> (asthénie, perte de poids).</li><li>Une <strong>douleur ou masse abdominale</strong>, liée à de volumineuses adénopathies rétropéritonéales.</li><li>Un <strong>ganglion de Troisier</strong> (sus-claviculaire gauche).</li><li>Exceptionnellement, une détresse respiratoire ou une toux en cas de métastases pulmonaires.</li></ul>"},{"i":"b8b081b8ef23","n":313,"o":"313-5","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du testicule","q":"Quelles sont les présentations locales atypiques des tumeurs du testicule ?","a":"<ul><li>Une <strong>douleur testiculaire subaiguë</strong> pouvant mimer un traumatisme, une orchite ou une torsion.</li><li>Une découverte fortuite lors d'une échographie réalisée dans le cadre d'un bilan d'infertilité.</li></ul>"},{"i":"ce5d84cf859e","n":313,"o":"313-5","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du testicule","q":"Comment une gynécomastie peut-elle orienter vers le diagnostic de tumeur testiculaire ?","a":"<p>Une gynécomastie peut être un signe paranéoplasique de tumeur testiculaire, notamment en cas de sécrétion tumorale d'<strong>hCG</strong>. C'est un élément qui oriente fortement vers la suspicion d'une <strong>tumeur germinale</strong>, en particulier un choriocarcinome ou d'autres TGNS (tumeurs germinales non séminomateuses).</p>"},{"i":"103d51b7b16a","n":313,"o":"313-6","u":"Diagnostic positif","t":"Connaître les modalités de l’examen clinique du testicule tumoral","q":"Quelle est la signification du signe de Chevassu positif lors de l'examen clinique d'une masse testiculaire ?","a":"<p>Un signe de Chevassu positif signifie que le <strong>sillon épididymo-testiculaire est conservé</strong>. Cela indique que l'on peut <strong>séparer au doigt le testicule de l'épididyme</strong>, signant ainsi l'<strong>origine testiculaire pure</strong> et intra-testiculaire de la masse, indépendamment de l'épididyme.</p>"},{"i":"4df75ba4f656","n":313,"o":"313-6","u":"Diagnostic positif","t":"Connaître les modalités de l’examen clinique du testicule tumoral","q":"Comment se caractérise la douleur associée à une tumeur testiculaire et quel est le résultat du test de transillumination ?","a":"<ul><li><strong>Douleur</strong> : La masse est classiquement <strong>indolore</strong>, même si elle peut être sensible. Une absence de douleur n'élimine pas le diagnostic, elle l'oriente au contraire.</li><li><strong>Transillumination</strong> : La masse est <strong>non transilluminable</strong>, contrairement à une hydrocèle.</li></ul>"},{"i":"6a2c449b1520","n":313,"o":"313-6","u":"Diagnostic positif","t":"Connaître les modalités de l’examen clinique du testicule tumoral","q":"Comment doit être réalisée la palpation d'une suspicion de tumeur testiculaire lors de l'examen clinique ?","a":"<p>La palpation doit être réalisée de manière <strong>comparative et bilatérale</strong>, d'abord en position <strong>debout</strong>, puis en position <strong>couchée</strong>.</p>"},{"i":"e69f5c113d13","n":313,"o":"313-6","u":"Diagnostic positif","t":"Connaître les modalités de l’examen clinique du testicule tumoral","q":"Quelle est la description classique de la consistance et du caractère d'une masse testiculaire tumorale ?","a":"<ul><li><strong>Consistance</strong> : La masse est <strong>dure</strong>, voire <strong>pierreuse</strong>.</li><li><strong>Caractère</strong> : Elle est <strong>unilatérale</strong>, <strong>circonscrite</strong>, et <strong>intra-scrotale</strong>.</li></ul>"},{"i":"006442951b2f","n":313,"o":"313-7","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Pourquoi la biopsie percutanée d'une tumeur germinale du testicule est-elle contre-indiquée ?","a":"<p>La biopsie percutanée (trans-scrotale) est <strong>absolument contre-indiquée</strong> car elle risque de :</p><ul><li><strong>Violer l'anatomie lymphatique</strong> : elle redirigerait le drainage lymphatique vers les ganglions inguinaux au lieu des ganglions rétropéritonéaux, le drainage testiculaire normal.</li><li><strong>Disséminer la tumeur</strong>.</li></ul><p>Le diagnostic histologique se fait donc <strong>uniquement sur la pièce d'orchidectomie</strong>.</p>"},{"i":"5182c007468a","n":313,"o":"313-7","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quel est le bilan biologique et d'imagerie à réaliser avant une orchidectomie pour une tumeur du testicule ?","a":"<p>Avant l'orchidectomie, le bilan comprend :</p><ul><li>La <strong>cryoconservation de sperme</strong> au CECOS (obligation médico-légale).</li><li>Le dosage des <strong>trois marqueurs sériques</strong> : <ul><li><strong>alpha-foetoprotéine (AFP)</strong></li><li><strong>bêta-hCG totale</strong></li><li><strong>lactate déshydrogénase (LDH)</strong></li></ul></li><li>Un <strong>TDM thoraco-abdomino-pelvien (TDM-TAP)</strong> pour le bilan d'extension.</li></ul>"},{"i":"5c2f926516e4","n":313,"o":"313-7","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Comment doit être mené l'examen clinique initial face à une suspicion de tumeur du testicule ?","a":"<p>L'examen clinique doit être <strong>bilatéral et comparatif</strong>, comprenant :</p><ul><li>La palpation testiculaire pour évaluer toute tuméfaction scrotale.</li><li>La recherche d'une <strong>gynécomastie</strong>.</li><li>La palpation des <strong>aires ganglionnaires</strong> (adénopathies cervicales, sus-claviculaires, inguinales, signe de Troisier).</li><li>La recherche d'une <strong>masse abdominale</strong>.</li></ul>"},{"i":"83c86d9d5191","n":313,"o":"313-7","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Comment doit être réalisée l'orchidectomie pour une tumeur du testicule et quelle est sa justification ?","a":"<p>L'orchidectomie doit être <strong>totale</strong> et <strong>élargie au cordon spermatique</strong>, par <strong>voie inguinale impérative</strong>. La justification est double : c'est le <strong>dernier geste diagnostique</strong> (permettant l'histologie définitive) et le <strong>premier geste thérapeutique</strong>. Une ligature première du cordon à l'orifice inguinal interne est essentielle, avec exérèse en bloc, et une prothèse testiculaire peut être proposée dans le même temps opératoire.</p>"},{"i":"b48f2bd3dd56","n":313,"o":"313-7","u":"Diagnostic positif","t":"Connaître la démarche diagnostique","q":"Quel est l'examen d'imagerie de première intention pour le diagnostic d'une tumeur testiculaire ?","a":"<p>L'examen d'imagerie de première intention est l'<strong>échographie scrotale bilatérale avec Doppler couleur</strong>. Elle permet de confirmer la localisation testiculaire de la lésion, d'éliminer une origine extra-testiculaire et d'orienter vers la nature maligne de la tuméfaction.</p>"},{"i":"1546c2bf69f8","n":313,"o":"313-8","u":"Examens complémentaires","t":"Connaître l’examen de première intention : échographie scrotale","q":"Quelles sont les trois missions de l'échographie scrotale dans l'exploration d'un nodule intra-testiculaire ?","a":"<ul><li>Confirmer la <strong>localisation testiculaire</strong> (et éliminer une origine extra-testiculaire).</li><li>Explorer le <strong>testicule controlatéral</strong> (recherche de tumeur synchrone, microcalcifications ou atrophie).</li><li>Orienter vers la <strong>nature maligne</strong>.</li></ul>"},{"i":"2371cf06d6b6","n":313,"o":"313-8","u":"Examens complémentaires","t":"Connaître l’examen de première intention : échographie scrotale","q":"Quel est l'examen paraclinique de première intention face à un nodule intra-testiculaire ?","a":"<p>L'<strong>échographie scrotale</strong> est l'examen paraclinique de première intention devant tout nodule intra-testiculaire.</p>"},{"i":"2450c04d7440","n":313,"o":"313-8","u":"Examens complémentaires","t":"Connaître l’examen de première intention : échographie scrotale","q":"Dans le contexte d'une suspicion de tumeur testiculaire, quel est le rôle de l'échographie scrotale par rapport au diagnostic histologique définitif ?","a":"<p>L'échographie scrotale <strong>ne fait jamais le diagnostic histologique</strong> ; elle ne fait qu'orienter. Le diagnostic de certitude reste l'<strong>orchidectomie</strong> avec analyse anatomopathologique.</p>"},{"i":"31408ac2a6aa","n":313,"o":"313-8","u":"Examens complémentaires","t":"Connaître l’examen de première intention : échographie scrotale","q":"Quels sont les aspects échographiques classiques des séminomes et des tumeurs germinales non séminomateuses (TGNS) ?","a":"<ul><li>Les <strong>séminomes</strong> apparaissent comme des masses <strong>lobulées</strong>, <strong>hypoéchogènes</strong> et assez homogènes, souvent associées à des microlithes.</li><li>Les <strong>TGNS</strong> sont volontiers des masses <strong>hétérogènes</strong> et polycycliques, mêlant plages kystiques et zones tissulaires mixtes.</li></ul>"},{"i":"76b9a642865a","n":313,"o":"313-8","u":"Examens complémentaires","t":"Connaître l’examen de première intention : échographie scrotale","q":"Comment l'échographie scrotale oriente-t-elle vers la nature maligne d'une tumeur testiculaire ?","a":"<p>Toute tumeur germinale est <strong>vascularisée au Doppler couleur</strong>. L'aspect échographique (homogène, hétérogène, kystique) peut également orienter vers le sous-type histologique, mais ne permet pas le diagnostic de certitude.</p>"}]};